import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

const ISOLATION_HEADERS = {
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Embedder-Policy": "require-corp",
};

// The screenshots are generated by the add-in itself (`make shots`) and live in
// the repository's docs/images; scripts/copy-images.mjs copies them into
// public/images before every build, so the site never carries its own copies.
export default defineConfig({
  plugins: [react()],
  base: "./",
  build: { outDir: "dist", assetsDir: "assets" },
  // The preview proxy reaches the server under its own hostname, so the host
  // check has to accept it; bind to 0.0.0.0 for the same reason.
  // The WebAssembly simulator hands keys and frames between the page and a
  // worker through a SharedArrayBuffer, which browsers only allow on a
  // cross-origin isolated page.  The same two headers are in vercel.json.
  server: {
    host: "0.0.0.0",
    port: 5173,
    allowedHosts: true,
    headers: ISOLATION_HEADERS,
  },
  preview: {
    host: "0.0.0.0",
    port: 4173,
    allowedHosts: true,
    headers: ISOLATION_HEADERS,
  },
});
